// neon.test.js — PARTIAL coverage (on purpose).
//
// What is covered today: the collision primitive and a couple of physics
// bounces. What is NOT covered yet: score and combo (see ISSUES.md #5), nor
// level progression. This is a starting point for the testing work ahead, not
// a complete suite.
//
// Run: `node --test "game/**/*.test.js"`  (or `npm test`)

import { test } from 'node:test';
import assert from 'node:assert/strict';

import {
  collides,
  step,
  makeBricks,
  createState,
  frame,
  BRICK_ROWS,
  BRICK_COLS,
  WIDTH,
  BALL_R,
} from './neon.js';

const mockCtx = {
  fillRect: () => {},
  arc: () => {},
  fill: () => {},
  beginPath: () => {},
  fillText: () => {},
};

test('collides: clear overlap detected', () => {
  const ball = { x: 100, y: 100, r: 8 };
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), true);
});

test('collides: ball clearly away => no collision', () => {
  const ball = { x: 300, y: 300, r: 8 };
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), false);
});

test('collides: edge contact (radius) detected', () => {
  const ball = { x: 85, y: 100, r: 8 }; // right edge of the ball at 93 > 90
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), true);
});

test('step: bounce off the left wall', () => {
  const state = createState(1);
  state.ball = { x: 2, y: 200, r: 7, vx: -300, vy: 0 };
  step(state, 1 / 60);
  assert.ok(state.ball.vx > 0, 'horizontal velocity should flip to the right');
});

test('step: ball exiting through the bottom => lost', () => {
  const state = createState(1);
  state.ball = { x: 320, y: belowField(), r: 7, vx: 0, vy: 400 };
  const lost = step(state, 1 / 60);
  assert.equal(lost, true);
});

test('makeBricks: full, all-alive grid at start', () => {
  const bricks = makeBricks(1);
  assert.equal(bricks.length, BRICK_ROWS * BRICK_COLS);
  assert.ok(bricks.every((b) => b.alive));
  assert.ok(bricks.every((b) => b.x >= 0 && b.x + b.w <= WIDTH));
});

test('frame: ball bounces off the top face of a brick', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  brick.x = 100; brick.y = 100; brick.w = 50; brick.h = 20;

  state.ball = { x: 125, y: 98, r: BALL_R, vx: 0, vy: -100 }; // hits top face

  frame(mockCtx, state);

  assert.equal(state.ball.vy, 100, 'ball should bounce DOWN after hitting TOP face');
  assert.ok(state.ball.y + BALL_R <= 100, 'ball should be pushed out of the brick');
});

test('frame: ball bounces off the bottom face of a brick', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  brick.x = 100; brick.y = 100; brick.w = 50; brick.h = 20;

  state.ball = { x: 125, y: 125, r: BALL_R, vx: 0, vy: 100 }; // hits bottom face (wait, vy > 0 is DOWN)
  // To hit bottom, it must be moving UP (vy < 0) and coming from below.
  state.ball.y = 120 + BALL_R + 2; // 129
  state.ball.vy = -100; // moving UP
  // ball.y - r = 122. Brick bottom is 120. Collision.

  frame(mockCtx, state);

  assert.equal(state.ball.vy, 100, 'Wait, if it hits bottom and was moving UP, it should move DOWN');
  // NO. If it hits the bottom face, it should bounce DOWN?
  // Wait.
  // Bottom face of brick is at y = 120.
  // Ball is at y = 127. Ball.y - r = 120.
  // If ball is moving UP (vy < 0), it hits the bottom face.
  // It should then move DOWN (vy > 0).
  // Wait, the TOP face is at 100. Bottom at 120.
  // If ball is at 127 and moving UP, it hits 120. It should bounce DOWN.
  // If ball is at 93 and moving DOWN, it hits 100. It should bounce UP.
  // Let's re-check conventions.
});

