test('frame: ball does not double-invert when hitting two bricks at once', () => {
  const state = createState(1);
  state.bricks.forEach(b => b.alive = false);
  const b1 = state.bricks[0];
  b1.alive = true; b1.x = 100; b1.y = 100; b1.w = 50; b1.h = 20;
  const b2 = state.bricks[1];
  b2.alive = true; b2.x = 158; b2.y = 100; b2.w = 50; b2.h = 20;

  // Ball centered on the gap: x=154. 
  // Ball right edge: 161 > b1.x+w (150) - No, ball.x-r = 147 < 150.
  // Ball left edge: 147. 
  // Ball.x = 154, r = 7. [147, 161].
  // b1: [100, 150]. overlap: [147, 150].
  // b2: [158, 208]. overlap: [158, 161].
  // Both collide.
  state.ball = { x: 154, y: 95, r: BALL_R, vx: 0, vy: 100 }; 

  frame(mockCtx, state);

  assert.equal(state.ball.vy, -100, 'ball should only bounce once');
});

